CREATE OR REPLACE FUNCTION public.processed_data_before_insert_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_month_start date := date_trunc('month', current_date)::date;
  v_momento text := normalize_momento(NEW."MOMENTO");
  v_has_manha boolean := false;
  v_tarde_count int := 0;
BEGIN
  IF (NEW."STATUS" IS NULL OR btrim(NEW."STATUS") = '') AND NEW."DATA" >= v_month_start THEN
    NEW."STATUS" := 'PENDENTE';
  END IF;

  IF v_momento = 'TARDE' THEN
    SELECT exists (
      SELECT 1 FROM processed_data
       WHERE "DATA" = NEW."DATA"
         AND "PROFISSIONAL" = NEW."PROFISSIONAL"
         AND normalize_momento("MOMENTO") = 'MANHA'
    ) INTO v_has_manha;

    IF v_has_manha THEN
      SELECT count(*) FROM processed_data
       WHERE "DATA" = NEW."DATA"
         AND "PROFISSIONAL" = NEW."PROFISSIONAL"
         AND normalize_momento("MOMENTO") = 'TARDE'
      INTO v_tarde_count;

      IF v_tarde_count >= 1 THEN
        NEW."STATUS" := 'ESPERAR';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_processed_data_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new."updated_at" := now();
  return new;
end;
$function$
